// Batch probe: reads a JSON array of markdown strings from argv[2] (file path),
// prints one JSONL line per input: {"md":..,"core":..,"tables":..,"extra":..}
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test11_executable';
